// -----------------------------------------------------------------------------
// UNA sola presentación por teléfono, sin precios, sin banco ni enlaces, sin «hablar con» nadie.
const RA_SALUDO_APERTURA = '¡Hola! Qué gusto saludarte 😊 Soy el asistente virtual de Antonio Dauber.';
