  if (/\b(psicolog\w*|terapeuta\w*|terapia)\b/.test(norm) && !/\bno (es|soy|hago|reemplaza|sustituye)\b/.test(norm)) return 'terapia';
  if (/\b(garantiz\w*|reconcili\w*|te aseguro|seguro que)\b/.test(norm)) return 'promesa_de_resultado';
  if (/\b(paquete|pack|bonos?|opciones de compra|botones?|elige|elegir)\b/.test(norm)) return 'oferta_fuera_del_codigo';
  if (/\b(testimonio|mariana|daniel)\b/.test(norm)) return 'testimonio';
  if (/\b(visita|visitar|visite|nuestra pagina|nuestro sitio|sitio web|pagina web|en la web|en internet)\b/.test(norm)) return 'remite_a_web';
  if (/\bderivar\b|\briesgo\b/.test(norm)) return 'palabra_interna';
  if (/descuent|gratis|gratuito|promoci|oferta|garant|devoluc|reembols/.test(norm)) return 'afirmacion_comercial';
  // El estado de un PAGO o de una ENTREGA lo dice solo el código (y Antonio): el modelo no habla de pagos, comprobantes ni compras, ni de si el material salió, llega, se procesa o va a un correo.
  // Cierres de pago con otras palabras («ya recibí todo», «todo listo con tu pago», «coinciden… todo listo»): también son el estado de un pago, y lo dice solo el código.
  if (/\bya recibi todo\b|\btodo listo\b|\bcoinciden?\b[^.?!]{0,60}\btodo (listo|bien|ok)\b/.test(norm)) return 'estado_de_pago';
  if (/\b(pago|pagos|pague|pagas|pagado|pagada|pagaste|pagamos|transferencia|transferencias|deposito|depositos|comprobante|comprobantes|abono|abonos|abonar|cobro|cobros|tu compra|su compra|tu pedido|su pedido|procesand\w*|procesad\w*|todo en orden|en orden)\b/.test(norm)) return 'estado_de_pago';
  if (/\b(material|libro|pdf|pdfs|archivo|archivos|bonos?|guia|enlaces?|link)\b[^.?!]{0,40}\b(llega\w*|llego|enviad\w*|envia\w*|enviar\w*|mand\w*|salio|salieron|sali\w*|listo|lista|listos|recibir\w*|recibid\w*|entreg\w*|descarg\w*|correo|email|mail)\b|\b(llega\w*|enviad\w*|envia\w*|enviar\w*|mand\w*|recibir\w*|entreg\w*)\b[^.?!]{0,40}\b(material|libro|pdf|pdfs|archivo|archivos|bonos?|guia|enlaces?|link)\b|\b(correo|email|mail|gmail)\b/.test(norm)) return 'estado_de_entrega';
  // Plazos: ningún «en unos minutos», «en pocas horas», «en un par de días», «pronto», «enseguida»… (con dígitos o sin ellos): el plazo es un dato del código.
  if (/\ben (unos|unas|pocos|pocas|breve|un par de|algunos|algunas|\d+|una|un|dos|tres|cuatro|cinco|seis|diez|veinte|treinta)\b[^.?!]{0,12}\b(minutos?|horas?|dias?|segundos?|momentos?|instantes?|ratos?|semanas?)\b|\b(pronto|prontito|enseguida|en seguida|ahora mismo|de inmediato|inmediatamente|en breve|muy pronto|dentro de poco|cuanto antes)\b/.test(norm)) return 'plazo';
  return '';
}

// =============================================================================
// UTILIDADES COMUNES DE LOS NODOS DEL FLUJO DE ANTONIO (prefijo `cn`)
// =============================================================================
// El constructor las pega entre la librería (`ra.js`, y las `cm*` en los nodos que las piden) y el código de cada nodo. JavaScript plano: sin `require`, `URL`,
// `Buffer` ni `crypto`, y nada de red. Lo que se lee de otro nodo se lee POR NOMBRE y solo si corrió (`isExecuted`): un nodo que no corrió no se lee con `.item`.
// Ningún nodo lee por nombre algo que corre más de una vez en la ejecución (no hay ciclos): `first()` es siempre «el único».

// El nodo `nombre` si existe Y corrió en esta ejecución; si no, null. En un JSON que no lo trae (el de producción no tiene «Entrada de prueba») `$()` lanza.
function cnNodo(nombre) {
  try {
    const n = $(nombre);
    return n && n.isExecuted ? n : null;
  } catch (e) {
    return null;
  }
}
function cnPrimero(nombre) {
  const n = cnNodo(nombre);
  if (!n) return null;
  try {
    const i = n.first();
    return i && i.json ? i.json : null;
  } catch (e) {
    return null;
  }
}
function cnTodos(nombre) {
  const n = cnNodo(nombre);
  if (!n) return [];
  try {
    return n.all().map((i) => (i && i.json) || {});
  } catch (e) {
    return [];
  }
}
function cnCfg() {
  return cnPrimero('Config del negocio') || {};
}
function cnDigitos(v) {
  return String(v === undefined || v === null ? '' : v).replace(/\D/g, '');
}
function cnRecorte(t, max) {
  const s = String(t === undefined || t === null ? '' : t);
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
}
// El texto de una respuesta de Gemini (generateContent, o el nodo de LangChain con `simplify`). '' si vino un error o algo que no se reconoce.
function cnTextoDeGemini(j) {
  if (!j || typeof j !== 'object' || j.error) return '';
  const partes = (c) => (c && Array.isArray(c.parts))
    ? c.parts.map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n') : '';
  if (typeof j.content === 'string') return j.content;
  const c1 = partes(j.content);
  if (c1) return c1;
  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const c2 = cand ? partes(cand.content) : '';
  if (c2) return c2;
  for (const k of ['text', 'transcription', 'output', 'response']) {
    if (typeof j[k] === 'string' && j[k].trim()) return j[k];
  }
  return '';
}
// El objeto JSON que Gemini devolvió como texto; null si no es un objeto.
function cnJsonDeGemini(j) {
  const t = cnTextoDeGemini(j).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  if (!t) return null;
  const m = /\{[\s\S]*\}/.exec(t);
  try {
    const o = JSON.parse(m ? m[0] : t);
    return o && typeof o === 'object' && !Array.isArray(o) ? o : null;
  } catch (e) {
    return null;
  }
}
// La clave de la ficha es el teléfono de origen y solo dígitos: nunca un nombre que toque el prototipo.
function cnClaveValida(from) {
  return /^\d{6,20}$/.test(String(from || ''));
}
// Las fichas de los teléfonos (`staticData.global.antonio`). Un nodo que SOLO LEE no escribe nada en los datos estáticos.
function cnMapaDeFichas(escribir) {
  let sd = null;
  try { sd = $getWorkflowStaticData('global'); } catch (e) { sd = null; }
  if (!sd) return { sd: null, mapa: {} };
  const valido = sd.antonio && typeof sd.antonio === 'object' && !Array.isArray(sd.antonio);
  if (!valido) {
    if (escribir !== true) return { sd: sd, mapa: {} };
    sd.antonio = {};
  }
  return { sd: sd, mapa: sd.antonio };
}
function cnFichaDe(mapa, from) {
  return cnClaveValida(from) && Object.prototype.hasOwnProperty.call(mapa, from) ? mapa[from] : null;
}
// La atención del teléfono: lo que devolvió la ingesta del entrante si lo trae, y si no, lo que dijo `configuracionFlujo`. Ante la duda, normal.
function cnAtencion(rIngesta, cfg) {
  const a = rIngesta && typeof rIngesta === 'object' && rIngesta.atencion && typeof rIngesta.atencion === 'object'
    ? rIngesta.atencion : null;
  const estados = ['normal', 'operador', 'bloqueado'];
  const estado = a && estados.indexOf(a.estado) >= 0 ? a.estado
    : (estados.indexOf(cfg.atencionEstado) >= 0 ? cfg.atencionEstado : 'normal');
  const avisarIngesta = rIngesta && typeof rIngesta === 'object' ? rIngesta.avisarRecepcion : '';
  const avisarCfg = a && a.avisarRecepcion !== undefined ? a.avisarRecepcion : cfg.atencionAvisarRecepcion;
  const avisar = ['operador', 'bloqueado'].indexOf(avisarIngesta || avisarCfg) >= 0 ? (avisarIngesta || avisarCfg) : '';
  return {
    estado: estado,
    avisar: avisar,
    mensajeFijo: String((a && a.mensajeFijo) || cfg.atencionMensajeFijo || '').trim(),
    respuestas: Number(a && a.respuestasEnVentana !== undefined ? a.respuestasEnVentana : cfg.atencionRespuestas) || 0,
    venceEn: String((a && a.ventanaVenceEn) || cfg.atencionVenceEn || ''),
  };
}

// DECIDIR TURNO: el CÓDIGO decide qué pasa en este turno; el modelo solo conversa. Devuelve un `plan` (nada de texto libre del modelo sale de aquí):
//
//   nada           la puerta cerró el turno (suspendido, uso extendido, pausa por persona): no se hace nada más;
//   fuera_pais     un número no boliviano: el texto fijo con el botón de Antonio, sin QR (a lo más una vez en 24 horas: lo exige «Normalizar entrada»);
//   riesgo         violencia o miedo (raíces sobre texto, transcripción o texto leído de una imagen; o la marca del modelo en «Armar mensajes»): corta la venta, sin botones ni QR ni precios;
//   saludo         la presentación (UNA vez por teléfono) y la pregunta de apertura, sin montos. EL PRIMER TURNO de un teléfono es SIEMPRE este saludo fijo, por código, salvo que el mensaje traiga una intención que el código
//                  atiende (prellenado, ángulo de anuncio, derivación, precio, producto confirmado): el modelo no abre la conversación;
//   angulo         una entrada por un anuncio: el modelo redacta la apertura con el ángulo como dato (o el texto fijo del ángulo);
//   complemento    el prellenado de un bono: su precio, el ahorro del Pack calculado por el código (si el Pack está disponible) y los botones;
//   menu           las opciones principales (Pack, Libro, Bonos) con sus precios;   bonos   la lista de los 4 bonos;   precio   «¿cuánto cuesta…?» ya saludado, por código;
//   qr             el QR con el monto del CATÁLOGO (prellenados de Pack y Libro, o un botón o una fila de producto);
//   qr_pendiente   ya hay un QR abierto Y el cliente habla de pagar o pide un producto: el recordatorio (un solo QR a la vez, un pedido = un producto). Si ya fue lo último que se le dijo, se escala a Antonio (`derivar` con `qr_insistente`).
//                  Cualquier otra pregunta con un QR abierto se responde (precio, catálogo, imágenes, resultado o el modelo) SIN botones de producto y SIN abrir otro QR (`qrAbierto: true`);
//   catalogo       «qué vendes», «catálogo», «lista», «opciones»: los productos con precio leídos del catálogo de la consola, por código;   imagenes   «¿tienes imágenes?»: texto fijo, el flujo no envía imágenes;
//   cancelar_cobro «cancela ese qr» con un QR abierto y sin comprobante: el servidor cierra el cobro (llamada síncrona) y sale `cobro_cerrado`; si el servidor no responde 200, sale la derivación `cancelacion`;   cobro_ya_cerrado   la segunda cancelación seguida;
//   comprobante    el resultado del cotejo traducido por `cbResultadoVenta`;
//   derivar        pasa a Antonio (factura, otro medio de pago, garantía, reclamo, una persona; producto agotado; sin QR utilizable; «cancela mi pedido» con un QR abierto: `cancelacion`; SIN CONFIGURACIÓN del negocio: `sin_configuracion`): aviso + botón;
//   resultado      «¿me garantiza recuperar mi relación?»: frase fija;
//   modelo         una conversación libre: llama al modelo (memoria de 15 mensajes) y, desde la segunda respuesta, le pone el menú;
//   imagen_otra, audio_fijo, otro   respuestas fijas a lo que no es un comprobante ni texto. `audio_fijo` también cubre una nota de voz CORTA o ininteligible (menos de 3 palabras): se pide repetirla; el modelo nunca la contesta.
//
// EL MONTO NUNCA SALE DEL CLIENTE NI DEL MODELO: es el precio del catálogo del producto (`raPrecio`). Un producto que no sea uno de los 6, o que esté agotado, no genera QR. Un botón es un botón solo si llegó
// como `interactive` (un texto que diga «b_pack» no lo es). Si hay un QR abierto lo dice el SERVIDOR (`cobro.pendiente`); `ficha.qrHastaMs` evita abrir dos seguidos mientras la consola se entera.
const cfg = cnCfg();
const t = cnPrimero('Normalizar entrada') || {};
const puerta = cnPrimero('Puerta del turno') || {};
const base = cnPrimero('Config base') || {};
const from = String(t.from || '');
const ahora = Number(t.ahoraMs) || Date.now();
let textoDelTurno = '';   // lo que escribió (o dijo) el cliente en este turno: «Armar mensajes» lo guarda en la memoria de la charla
const salir = (plan, extra) => [{ json: Object.assign({ plan: plan, from: from, textoCliente: textoDelTurno, llamarModelo: false, cuerpoModelo: null, modelo: raModeloValido(base.modelo) }, extra || {}) }];
const panel = raPanelDe(cnPrimero('Traer configuración'));
const cat = raCatalogo(panel.cuerpo);
const agotados = raAgotados(panel.cuerpo);
const cobro = raCobro(panel);
const ficha = raFichaVigente(cnFichaDe(cnMapaDeFichas(false).mapa, from), ahora);

// 0. LA PROTECCIÓN ANTE VIOLENCIA O MIEDO VA PRIMERO, también con la puerta cerrada y fuera del país: si el comercio está suspendido, el estado es «operador» (el cliente sí recibe un mensaje) o el número no es
//    boliviano, un texto de riesgo recibe el texto de protección y reporta `no_contactar`, nunca el texto neutro, el aviso de uso extendido ni el de «pago con QR boliviano». La pausa por persona («bloqueado»)
//    sigue en silencio: ahí responde Antonio. Aquí solo se mira el texto y el pie (los medios no se bajan con la puerta cerrada ni fuera del país).
const riesgoEscrito = ficha.riesgo || raEsRiesgo(raNorm([t.texto, t.pie].join(' ')));
const puertaResponde = puerta.ruta === 'sigue' || puerta.ruta === 'suspendido' || (puerta.ruta === 'uso_extendido' && puerta.responder === true);
if (puertaResponde && puerta.ruta !== 'sigue' && riesgoEscrito) return salir({ tipo: 'riesgo', aviso: null, cat: cat });
if (puerta.ruta !== 'sigue') return salir({ tipo: 'nada' });

// 0b. Un número no boliviano: el texto fijo y el botón de Antonio. Nada de modelo, de medios ni de QR.
if (t.fueraDePais === true) return salir(riesgoEscrito ? { tipo: 'riesgo', aviso: null, cat: cat } : { tipo: 'fuera_pais', cat: cat });

// El medio de este turno (solo uno de estos nodos corrió) y lo que se leyó en él.
const prep = cnPrimero('Preparar imagen') || cnPrimero('Preparar transcripción') || cnPrimero('Medio no aceptado') || {};
const entradaMedio = String(prep.userInput || '');
const esAudio = t.esMedioAudio === true;
const esVisual = t.esMedioVisual === true;
const categoriaMedio = String(prep.categoriaMedio || '');
// El texto leído en la imagen es un DATO del cliente: solo sirve para reconocer el ángulo del anuncio y para detectar riesgo; nunca llega al modelo como instrucción.
const jsonImagen = esVisual ? (cnJsonDeGemini(cnPrimero('Describir documento') || cnPrimero('Describir imagen')) || {}) : {};
const leido = esVisual && typeof jsonImagen.texto === 'string' ? raLineaCliente(jsonImagen.texto, 500) : '';
// La nota de voz: el texto transcrito (la primera línea), o la falla.
let transcrito = '';
let falloAudio = '';
if (esAudio) {
  if (/^\(audio transcripto\) /.test(entradaMedio)) transcrito = entradaMedio.slice('(audio transcripto) '.length).split('\n')[0].trim();
  else if (/más de cinco minutos/.test(entradaMedio)) falloAudio = 'largo';
  else if (/no se pudo entender/.test(entradaMedio)) falloAudio = 'no_entendido';
  else falloAudio = 'no_abierto';
}
const textoCliente = t.tipo === 'interactive' ? '' : (esAudio ? transcrito : String(t.texto || ''));
const norm = raNorm(textoCliente);
textoDelTurno = raLineaCliente(textoCliente, 300).replace(/\s+/g, ' ').trim();
// Un «Sí» o un «No» suelto con una pregunta nuestra vigente (30 min): el modelo recibe la pregunta como dato y qué hacer con ella. Sin pregunta vigente, nada.
const respSuelta = !esVisual && ficha.ultimaPregunta !== '' ? raRespuestaSuelta(norm) : '';
const respuestaAPregunta = respSuelta ? { tipo: respSuelta, pregunta: ficha.ultimaPregunta } : null;

// El aviso de consulta a Antonio lleva el MOTIVO exacto (`clave` + `motivo`). El límite (a lo más UN aviso cada 30 minutos por teléfono Y por motivo) lo aplica «Armar avisos», que ve la ficha.
const avisoDeConsulta = (clave, motivo) => ({ tipo: 'consulta', clave: clave, motivo: motivo, mensaje: t.tipo === 'interactive' ? '' : String(textoCliente || leido).slice(0, 200) });
// EL RECORDATORIO DEL QR ABIERTO (solo si el cliente habla de pagar o pide un producto). Nunca el mismo recordatorio dos veces seguidas: si ya fue lo último que se le dijo (`ficha.ultimaFirma`), se escala a Antonio.
const recordatorio = (boton) => (ficha.ultimaFirma === 'qr_pendiente'
  ? { tipo: 'derivar', motivo: 'qr_insistente', clave: 'qr_insistente', aviso: avisoDeConsulta('qr_insistente', 'insiste con un QR abierto: ya se le recordó el pago'), cat: cat, boton: boton || '' }
  : { tipo: 'qr_pendiente', producto: producto, monto: cobro.monto, cat: cat, boton: boton || '' });
const sinOpciones = (boton) => ({ tipo: 'derivar', motivo: 'sin_opciones', aviso: avisoDeConsulta('qr_no_disponible', 'sin opciones de compra disponibles'), cat: cat, boton: boton });
const hayQrAbierto = cobro.pendiente === true || ficha.qrHastaMs > ahora;
const hayCobro = cobro.modo === 'real' && (cobro.pendiente || cobro.enRevision || cobro.vencidoHaceMin !== null);
const producto = ficha.producto || '';
const nombreProducto = producto && RA_PRODUCTOS[producto] ? RA_PRODUCTOS[producto].nombre : 'sin producto';

// El resultado del cotejo (si corrió) como plan de comprobante. Solo corrió si la imagen era un comprobante y había un cobro real; si no, «cbResultadoVenta» lo deja en «sin cotejar» con aviso y botón: nunca «cuadra».
const planComprobante = () => {
  const resp = cnNodo('Cotejar en el servidor') ? cnPrimero('Cotejar en el servidor') : null;
  const r = cbResultadoVenta(resp);
  const avisa = r.resultado === 'cuadra' || r.resultado === 'aproximado' || r.resultado === 'sin_cotejo';
  const motivoSrv = cbCuerpoDe(resp).cuerpo.motivo;
  const motivoAviso = r.resultado === 'aproximado' ? raMotivoComprobante('aproximado', motivoSrv) : (r.resultado === 'sin_cotejo' ? raMotivoComprobante(r.causa, motivoSrv) : '');
  return {
    tipo: 'comprobante', resultado: r.resultado, causa: r.resultado === 'aproximado' && motivoSrv === 'monto_distinto' ? 'monto_distinto' : r.causa, diferencia: r.resultado === 'reintentar' ? cbDiferencia(r.diferencias, 'Bs') : '', cat: cat, producto: producto,
    aviso: avisa ? { tipo: 'comprobante', resultado: r.resultado, producto: nombreProducto, monto: cobro.monto, motivo: motivoAviso, clave: r.resultado === 'sin_cotejo' && !r.causa ? 'comprobante_sin_cotejo' : '' } : null,
  };
};

// 1. VIOLENCIA O MIEDO: antes que cualquier otra cosa (corta la venta). Se mira el texto, la transcripción, el texto leído de la imagen y el pie de foto; una vez activada, sigue activa 48 horas. El turno que trae
//    un COMPROBANTE (imagen o PDF) sigue su camino normal del cobro (cotejo y aviso a Antonio): el riesgo se detecta solo en turnos sin comprobante pendiente de cotejar. Sin aviso a Antonio, sin consejos.
if (!(esVisual && categoriaMedio === 'comprobante') && (ficha.riesgo || raEsRiesgo(raNorm([textoCliente, leido, t.pie].join(' '))))) {
  return salir({ tipo: 'riesgo', aviso: null, cat: cat });
}

// 1b. Lo que no necesita la configuración del negocio: una nota de voz que no se pudo usar (o que es corta o ininteligible: se pide repetirla, nunca la contesta el modelo) y lo que este canal no lee.
//     (La nota de voz corta con una intención clara —«hola», «quiero el pack»— no llega aquí: la atiende el código más abajo.)
if (esAudio && falloAudio) return salir({ tipo: 'audio_fijo', causa: falloAudio, cat: cat });
if (t.categoria === 'otro') return salir({ tipo: 'otro', cat: cat });
// 1c. SIN CONFIGURACIÓN (PR-D, orden de Andres): si «Traer configuración» falló o no trae catálogo, cobro ni venta, el flujo NO improvisa (ni el modelo, ni «no puedo mostrarte el QR» como si solo faltara el QR, ni precios):
//     texto honesto, aviso a Antonio y botón. El comprobante de una imagen tampoco se coteja a ciegas.
if (raSinConfiguracion(panel)) {
  // Con una imagen o un PDF el aviso dice que pudo ser un comprobante, sin copiar texto del cliente.
  const aviso = esVisual
    ? { tipo: 'consulta', clave: 'sin_configuracion', motivo: 'envió una imagen (posible comprobante) mientras la configuración no estaba disponible', mensaje: '' }
    : avisoDeConsulta('sin_configuracion', 'el asistente no pudo leer la configuración del negocio (catálogo, cobro o venta)');
  return salir({ tipo: 'derivar', motivo: 'sin_configuracion', clave: 'sin_configuracion', aviso: aviso, cat: cat });
}

// 2. Una imagen o un documento.
if (esVisual) {
  if (cnNodo('Medio no aceptado')) {
    // Demasiado pesado o ilegible: con un cobro real abierto probablemente sea el comprobante, y entonces va a Antonio sin cotejar; si no, se pide uno más liviano.
    if (hayCobro) return salir(Object.assign(planComprobante(), { resultado: 'sin_cotejo', causa: '', aviso: { tipo: 'comprobante', resultado: 'sin_cotejo', producto: nombreProducto, monto: cobro.monto, motivo: raMotivoComprobante('', ''), clave: 'comprobante_sin_cotejo' } }));
    return salir({ tipo: 'archivo', pesado: /demasiado pesado/.test(entradaMedio), cat: cat });
  }
  if (categoriaMedio === 'comprobante') {
    if (cnNodo('Cotejar en el servidor')) return salir(planComprobante());
    // Un comprobante sin cobro abierto: no se coteja nada; lo ve Antonio.
    return salir({ tipo: 'derivar', motivo: 'comprobante_sin_cobro', clave: 'comprobante_sin_cobro', aviso: avisoDeConsulta('comprobante_sin_cobro', 'recibió una imagen que parece un comprobante, pero no hay un QR abierto'), cat: cat });
  }
  // La captura de un pago rechazado, pendiente o con error: nunca se coteja ni se afirma qué pasó con el dinero. Lo ve Antonio: aviso con ese motivo (a lo más uno cada 30 minutos por teléfono) y el botón.
  if (categoriaMedio === 'pago_con_problema') {
    return salir({ tipo: 'derivar', motivo: 'pago_con_problema', clave: 'pago_con_problema', aviso: { tipo: 'consulta', clave: 'pago_con_problema', motivo: 'envió la captura de un pago que parece no haberse completado', mensaje: '' }, cat: cat });
  }
  // Foto, captura de pantalla, «otro» (y la categoría inventada, que ya cayó en «otro») y una publicidad cuyo ángulo no se reconoce: el asistente dice lo que ve (descripción ya saneada por «Preparar imagen»; en una publicidad,
  // una frase fija del código) y ofrece el libro y los precios. Una publicidad con ángulo conocido sigue más abajo (apertura del ángulo).
  if (categoriaMedio !== 'publicidad' || raAngulo(raNorm(leido)) === '') {
    // Segunda barrera sobre la descripción: si traía un enlace, un correo, una cifra larga, un dominio o un delimitador, el módulo común lo quitó y quedaría una frase mutilada («Veo escribe a»): se descarta ENTERA.
    const cruda = String(jsonImagen.descripcion || '');
    const mutilada = /https?:|www\.|@|\d[\d\s.\-\/,]{3,}\d|\b\S+\.(?:com|net|org|bo|io|app|me|link|ly)\b|[\[\]{}<>«»"'`*_\\|#]/i.test(cruda);
    // Tercera barrera (revisión de seguridad de #602): la descripción se muestra tal cual al cliente, así que NO puede prometer ni afirmar nada (reembolso, devolución, descuento, regalo, dinero), ni afirmar un pago (`CB_PROHIBIDAS`), ni negar ser una IA.
    // Se mira la cruda y la saneada. No se descarta por «antonio» ni por «pago» a secas: el logo del comercio y «pago no se completó» siguen funcionando.
    const prometedora = [cruda, String(prep.descripcionMedio || '')].some((x) => {
      const n = raNorm(x);
      return /reembols|devol|devuelt|reintegr|anulad|rechazad|gratis|gratuit|descuent|promet|promoci|oferta|garant|regal|dinero|plata/.test(n) || CB_PROHIBIDAS.test(cbCanon(x)) || RA_NIEGA_IA.test(n);
    });
    const descripcion = categoriaMedio === 'publicidad' ? 'una imagen publicitaria' : (mutilada || prometedora ? '' : String(prep.descripcionMedio || ''));
    return salir({ tipo: 'imagen_descrita', documento: t.esDocumento === true, descripcion: descripcion, cat: cat });
  }
  // Una captura de anuncio: se reconoce el ángulo por el texto leído; sin ángulo, se sigue como una charla.
}

// 5. Elegir un producto: el QR con el monto del catálogo. Devuelve el plan.
const elegir = (k, boton) => {
  if (hayQrAbierto) return recordatorio(boton);
  if (cobro.enRevision === true) return { tipo: 'derivar', motivo: 'en_revision', aviso: null, cat: cat, boton: boton };
  const precio = raPrecio(cat, k);
  const agotado = agotados.indexOf(k) >= 0;
  const sinQr = precio === null ? (agotado ? 'agotado' : 'sin_precio') : (cobro.modo === 'ninguno' ? 'sin_cobro' : (cobro.mediaId === '' ? 'sin_medio' : ''));
  if (sinQr === 'agotado') return { tipo: 'derivar', motivo: 'agotado', aviso: avisoDeConsulta('producto_agotado', 'pidió ' + RA_PRODUCTOS[k].nombre + ', que figura como agotado'), cat: cat, boton: boton };
  if (sinQr) return { tipo: 'derivar', motivo: sinQr, aviso: avisoDeConsulta('qr_no_disponible', 'QR no disponible (' + sinQr + ')'), cat: cat, boton: boton };
  return { tipo: 'qr', producto: k, monto: precio, mediaId: cobro.mediaId, pedidoId: raIdPedido(ahora, ficha.pedidos + 1), conPresentacion: !ficha.saludado, cat: cat, boton: boton };
};
// Las opciones principales: el menú si queda algún botón; si no, la lista de bonos; si ninguna, Antonio (nunca «¿cuál prefieres?» sin opciones).
const opcionesDe = (usados, boton) => (raMenu(cat, usados).length ? { tipo: 'menu', cat: cat, boton: boton } : (raFilasBonos(cat, usados).length ? { tipo: 'bonos', cat: cat, boton: boton } : sinOpciones(boton)));
const saludo = (boton) => ({ tipo: 'saludo', cat: cat, boton: boton || '' });

// 6. Un toque de botón o de fila (solo si llegó como interactivo y es uno de los nuestros).
if (t.tipo === 'interactive') {
  const id = String(t.seleccionId || '');
  const k = raProductoDeBoton(id);
  if (k) return salir(elegir(k, id));
  if (id === RA_BOTON_BONOS) {
    if (hayQrAbierto) return salir(recordatorio(id));
    if (!ficha.saludado) return salir(saludo(id));
    return salir(raFilasBonos(cat, ficha.usados.concat([id])).length ? { tipo: 'bonos', cat: cat, boton: id } : sinOpciones(id));
  }
  // Un toque que no es de este flujo (un botón viejo, una lista de otro mensaje): nunca se toma por una conversación libre. Con un QR abierto, el recordatorio del QR; la primera vez, el saludo; ya saludado, las opciones.
  if (hayQrAbierto) return salir(recordatorio(id));
  if (ficha.saludado) return salir(opcionesDe(ficha.usados, ''));
  return salir(saludo());
}

// 7. Texto (escrito o transcrito): los prellenados de la landing, la derivación, el resultado, los ángulos de anuncio, el precio y la conversación.
const pre = raPrellenado(norm);
if (pre === 'pack' || pre === 'libro') return salir(elegir(pre, ''));
if (pre === 'info') return salir(hayQrAbierto ? recordatorio('') : saludo());
if (pre === 'workbook' || pre === 'calendario_preguntas') {
  const productos = pre === 'workbook' ? ['workbook'] : ['calendario', 'preguntas'];
  if (hayQrAbierto) return salir(elegir(productos[0], ''));
  // Sin el precio del bono o sin botones que ofrecer, «¿con cuál prefieres avanzar?» no tendría opciones: se deriva a Antonio.
  const hayPrecio = productos.some((k) => raPrecio(cat, k) !== null);
  return salir(!hayPrecio || !raMenuDeBonos(productos, cat, ficha.usados).length ? sinOpciones('') : { tipo: 'complemento', productos: productos, cat: cat, conPresentacion: !ficha.saludado });
}
const derivacion = raDerivacion(norm, { comprobante: ficha.comprobanteMs > 0 || cobro.enRevision === true, qrAbierto: hayQrAbierto });
if (derivacion) return salir({ tipo: 'derivar', motivo: 'consulta', clave: derivacion.clave, aviso: avisoDeConsulta(derivacion.clave, derivacion.motivo), cat: cat });
// «Cancela mi pedido», «no quiero comprar», «ya no lo quiero» (con un QR abierto o un pedido hecho). «Solo quiero saber…» no cancela nada: es un cliente que mira (se le responde más abajo).
// CANCELAR POR CÓDIGO: (a) QR abierto de regla 2 que el servidor ve (`cobro.pendiente`) y SIN comprobante previo: plan `cancelar_cobro`; «Cancelar cobro en el servidor» reporta `cobro_cancelado` ANTES de armar el texto
// y «Armar mensajes» dice «cerré tu pedido» solo si el servidor respondió 200; si no, cae a la escalada de siempre (`aviso` de este plan). (c) Con comprobante previo (en revisión o ya cotejado) NO se cancela: se escala y se
// reporta `anulacion_avisada` (solo avisa). Una segunda cancelación seguida recibe «ya cerrado» (la firma del último plan), sin repetir nada.
const cancelacion = raCancelaPedido(norm);
if (cancelacion === 'cancela') {
  if (ficha.ultimaFirma === 'cobro_cerrado' || ficha.ultimaFirma === 'cobro_ya_cerrado') return salir({ tipo: 'cobro_ya_cerrado', aviso: null, cat: cat });
  const conComprobante = ficha.comprobanteMs > 0 || cobro.enRevision === true;
  if (hayQrAbierto || ficha.pedidos > 0 || conComprobante) {
    const escalada = avisoDeConsulta('cancelacion', 'quiere cancelar su pedido o ya no quiere comprar (el cobro no se pudo cerrar desde el asistente)');
    if (!conComprobante && cobro.pendiente === true && cobro.regla === 2) {
      return salir({ tipo: 'cancelar_cobro', aviso: escalada, avisoCerrado: { tipo: 'consulta', clave: 'cancelacion', motivo: 'cerró su pedido; si pagó, revisar', mensaje: '' }, cat: cat, liberaGuarda: true });
    }
    return salir(Object.assign({ tipo: 'derivar', motivo: 'cancelacion', clave: 'cancelacion', aviso: escalada, cat: cat, liberaGuarda: hayQrAbierto }, conComprobante ? { evento: 'anulacion_avisada' } : {}));
  }
}
if (raPreguntaPorResultado(norm)) return salir({ tipo: 'resultado', cat: cat, qrAbierto: hayQrAbierto });
// CON UN QR ABIERTO (PR-D, «como Rubén»): el recordatorio SOLO sale si el cliente habla de pagar («ya pagué», «cómo pago», «comprobante», «QR», «monto») o pide un producto (más abajo). Todo lo demás se responde
// (resultado, imágenes, catálogo, precio, o el modelo para una pregunta) sin botones de producto y SIN abrir otro QR (`qrAbierto: true`).
if (hayQrAbierto && raHablaDelCobro(norm)) return salir(recordatorio(''));
// «¿Tienes imágenes?»: respuesta fija, el flujo no envía imágenes del libro. Como PRIMER mensaje, el saludo.
if (raPideImagenes(norm)) return salir(!ficha.saludado ? saludo() : { tipo: 'imagenes', cat: cat, qrAbierto: hayQrAbierto });
// El catálogo completo con precio, por código (texto y audio transcrito). Como PRIMER mensaje, el saludo (ningún primer mensaje lleva montos). Sin ningún precio en el catálogo, Antonio.
if (raPideCatalogo(norm)) {
  if (!ficha.saludado) return salir(saludo());
  return salir(Object.keys(cat).length ? { tipo: 'catalogo', cat: cat, qrAbierto: hayQrAbierto } : sinOpciones(''));
}
// El ángulo del anuncio: por el texto escrito o por el texto leído de una captura (publicidad). El modelo redacta la apertura con el ángulo como dato; si falla, sale el texto fijo del ángulo.
const angulo = raAngulo(norm) || (esVisual ? raAngulo(raNorm(leido)) : '');
if (angulo && !hayQrAbierto) {
  return salir({ tipo: 'angulo', angulo: angulo, conPresentacion: !ficha.saludado, cat: cat, textoCliente: String(textoCliente || leido).slice(0, 500) }, {
    llamarModelo: true, cuerpoModelo: raCuerpoModelo(textoCliente || leido, ficha.hist, RA_ANGULOS[angulo].tema, base.temperatura, respuestaAPregunta),
  });
}
// Una pregunta de precio: el PRIMER mensaje recibe el saludo, SIN monto; ya saludado, el precio exacto sale POR CÓDIGO desde el catálogo, sin modelo, con el menú. Sin ningún precio en el catálogo se deriva a Antonio.
const precioPedido = raPreguntaPorPrecio(norm);
if (precioPedido) {
  if (!ficha.saludado) return salir(saludo());
  return salir(Object.keys(cat).length ? { tipo: 'precio', producto: precioPedido.producto, cat: cat, qrAbierto: hayQrAbierto } : sinOpciones(''));
}
// La confirmación en texto (o por voz) de UN producto: el QR con el monto del catálogo, como un botón.
const confirmado = raProductoConfirmado(norm);
if (confirmado) return salir(elegir(confirmado, ''));
if (raQuiereOpciones(norm)) return salir(hayQrAbierto ? recordatorio('') : (ficha.saludado ? opcionesDe(ficha.usados, '') : saludo()));
if (!ficha.saludado && raEsSoloSaludo(norm)) return salir(saludo());
// Después de un comprobante recibido, hablar de pago, libro, material o entrega NO es una charla libre (y esto va DESPUÉS de las preguntas de precio, la confirmación de un producto y «cómo pago», que son una compra nueva): el modelo no habla del estado de un pago ni de una entrega. Va la derivación de no entrega
// (texto fijo con el plazo del dato, aviso y botón).
if (ficha.comprobanteMs > 0 && (raHablaDePagar(norm) || /\b(pago|pague|pagado|pagaste|comprobante|transferencia|deposito|material|llega\w*|llego|enviar\w*|enviaron|mandar\w*|mandaron|recib\w*|entrega\w*)\b/.test(norm) || (/\blibro\b/.test(norm) && /\b(cuando|donde|llega\w*|llego|envi\w*|mand\w*|recib\w*)\b/.test(norm)))) {
  return salir({ tipo: 'derivar', motivo: 'consulta', clave: 'no_entrega', aviso: avisoDeConsulta('no_entrega', 'queja de no entrega: el cliente pregunta por su pago o por el material'), cat: cat });
}
// Una nota de voz corta o ininteligible (menos de 3 palabras o sin letras que valgan) que el código no atendió arriba (ni siquiera la derivación de no entrega tras un comprobante, que va antes): se pide repetirla
// con un texto fijo; el modelo no inventa una respuesta.
if (esAudio && raAudioIlegible(norm)) return salir({ tipo: 'audio_fijo', causa: 'corto', cat: cat });
// Con un QR abierto, lo que queda: pedir un producto (recordatorio), una pregunta (el modelo, sin botones de producto ni otro QR) o cualquier otra cosa (recordatorio).
if (hayQrAbierto) {
  if (raPideProducto(norm) || !raEsPreguntaLibre(textoCliente, norm)) return salir(recordatorio(''));
  return salir({ tipo: 'modelo', cat: cat, qrAbierto: true, textoCliente: String(textoCliente).slice(0, 500) }, {
    llamarModelo: true, cuerpoModelo: raCuerpoModelo(textoCliente, ficha.hist, '', base.temperatura, respuestaAPregunta),
  });
}
// EL PRIMER TURNO de un teléfono (PR-D, [B]): el saludo fijo por código —la presentación una sola vez y la pregunta abierta, sin montos—; el modelo no abre la conversación. Lo que dijo queda en la memoria
// de la charla (el plan `saludo` la guarda), así que el modelo lo lee en la respuesta siguiente.
if (!ficha.saludado) return salir(saludo());
const paraElModelo = esVisual ? 'El cliente envió la captura de un anuncio. Texto leído: ' + leido : textoCliente;
return salir({ tipo: 'modelo', cat: cat, textoCliente: String(paraElModelo).slice(0, 500) }, {
  llamarModelo: true, cuerpoModelo: raCuerpoModelo(paraElModelo, ficha.hist, '', base.temperatura, respuestaAPregunta),
});

// =============================================================================
// COBRO DEL FLUJO DE ANTONIO (prefijo `cb` / `CB_`): HUECO DECLARADO en PROPIO.md
// =============================================================================
// COPIA, declaración por declaración y BYTE A BYTE, de `Flujos/experimental/venta-minima/src/lib/cobro.js` (rama #519, `cartera/qtaco-visor-comprobantes`): el módulo común de
// Cobros todavía no existe. Cada declaración tiene su prueba contra el origen en `huecos.test.ts` («HUECOS del cobro»); si el origen cambia, la prueba falla y obliga a decidir.
// Lo que NO se copia: los textos al cliente de un restaurante (`cbTextoAlCliente`), el QR por dirección (`cbMensajeQr`: aquí el QR sale como `image:{id}`, nunca con `link`)
// ni el cobro simulado por dirección. JavaScript plano: sin `require`, `URL`, `Buffer` ni `crypto`, sin red y sin reloj.

// La red de palabras de `comun.js` (`VM_PROHIBIDAS`), copiada acá a propósito: esta
// librería se prueba sola y no puede depender de otro archivo.
const CB_PROHIBIDAS = /validad|confirmad|pagad[oa]|acreditad|verificad|recibimos\s+tu\s+pago|ya lo prepar|lo (est[aá](n|mos)|estoy) prepar|lo preparamos|te avisa(mos|remos)|en camino|te llama(mos|remos)|te escribir[aá]n|lo consulto|acredit|recib\S{0,40}\s+(tu|el|su|mi|un|este|ese|la|tus|sus|los)\s+(pago|transferencia|dep[oó]sito|abono)s?|lleg[oó]\s+(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)|(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad)|confirm(amos|ó|o)\s+(tu|tus|su|sus|la|el|lo|los|las)\b|\b(?:est[aá]n?|qued[oó]|queda|quedan|quedaron|fue|fueron|ya)\s+(?:ya\s+)?reservad|reserva\s+((est[aá]|qued[oó])\s+)?(registrad|agendad)|reservamos tu|\b(?:te|le|les|se|lo|la|ya)\s+confirm(?:o|amos|é|ó|aron)\b|gracias\s+por\s+(tu|su|el)\s+(pago|transferencia|dep[oó]sito|abono)s?|\b(lleg|ingres|entr)(o|ó|aron)\s+(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)|\b(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|\brecib(imos|i|í|ido)\s+(el|la|tu|su)\s+(dinero|plata|monto)|(pago|transferencia|dep[oó]sito|abono|cobro)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+|qued[oó]\s+|se\s+)?(ya\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad|aceptad|completad|procesad|reflejad|comprobad)|\breflej(o|ó)\s+(tu|el|su)\s+(pago|transferencia|dep[oó]sito|abono)|\b(verificamos|comprobamos|validamos|aceptamos|tenemos|vimos|cobramos)\s+(tu|tus|su|sus|el|la)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata)|\bpago\s+(listo|ok)\b|\b(tu|su|el)\s+pago\s+(ya\s+)?(est[aá]|qued[oó])\s+(ya\s+)?(listo|ok|en\s+orden|bien|correcto|completo|hecho)\b|en\s+orden\s+con\s+(tu|su|el)\s+pago|\bsaldad[oa]s?\b|\b(pedido|cuenta|pago|total|orden|deuda)s?\s+((ya\s+)?(est[aá]n?|qued[oó]|fue|queda)\s+)?(ya\s+)?cancelad[oa]s?\b|\bya\s+nos\s+pag(aste|o|ó|aron)\b|\bgracias\s+por\s+pagar\b|\bya\s+pagaste\W{0,3}\s*(muchas\s+)?gracias|\brecib(imos|i|í|ido)\s+(bs\.?\s*|bob\s*)?\d+([.,]\d+)?\s*(bs|bob|bolivianos)\b|\bconfirm(amos|e|é)\s+que\s+(ya\s+)?pag|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?se\s+reflej/i;

// El total que acepta el servidor para cotejar (`TOTAL_VENTA_MAXIMO`).
const CB_TOTAL_MAXIMO = 1000000;

// El rótulo del QR simulado en el pie (el otro va IMPRESO en la imagen): sin él, el simulado no sale (PROHIBICIÓN 3).
const CB_ROTULO_SIMULADO = 'PRUEBA · COBRO SIMULADO: este QR es de demostración, no cobra ni mueve dinero.';

// Confusables latino/cirílico/griego plegados a ASCII SOLO para comparar (S-1); las dos cadenas van en paralelo, letra por letra.
const CB_CONFUSABLES_DE = 'аеорсухіјѕԁһӏ' + 'αεικορτυχνηβı';

const CB_CONFUSABLES_A = 'aeopcyxijsdhl' + 'aeikoptuxvnbi';

// La forma en que se COMPARA contra `CB_PROHIBIDAS` (S-1): NFKC, sin controles C1 (\u0080-\u009f) ni caracteres de formato
// (`\p{Cf}`), NFD sin marcas (`\p{M}`), en minúsculas y con los confusables plegados a ASCII.
function cbCanon(t) {
  return String(t === undefined || t === null ? '' : t).normalize('NFKC').replace(/[\u0080-\u009f]/g, '').replace(/\p{Cf}/gu, '').replace(/[\u115f\u1160\u3164\uffa0\u2800]/g, '')
    .normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[Ͱ-ϿЀ-ԯı]/g, (c) => {
      const i = CB_CONFUSABLES_DE.indexOf(c);
      return i < 0 ? c : CB_CONFUSABLES_A.charAt(i);
    });
}

// Una línea de texto: sin controles, sin `<>&`, espacios colapsados, recortada.
function cbLinea(t, max) {
  const s = String(t === undefined || t === null ? '' : t)
    .replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/[<>&]/g, '').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max).trimEnd() : s;
}

function cbEsObjeto(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

// El total de un pedido: SOLO un número del código. Un texto («63»), NaN, cero, un
// negativo o uno por encima del tope del servidor no son un total: devuelve null.
function cbTotalValido(v) {
  if (typeof v !== 'number' || !Number.isFinite(v)) return null;
  const r = Math.round(v * 100) / 100;
  return r > 0 && r <= CB_TOTAL_MAXIMO ? r : null;
}

// «55» o «12,50»: enteros sin decimales, y con coma decimal (así se lee en Bolivia).
function cbMonto(n) {
  const c = Math.round(Number(n) * 100);
  if (!Number.isFinite(c)) return '';
  const a = Math.abs(c);
  const cen = a % 100;
  return (c < 0 ? '-' : '') + Math.floor(a / 100) + (cen ? ',' + (cen < 10 ? '0' : '') + cen : '');
}

function cbMoneda(m) {
  const s = cbLinea(m, 8);
  return s === '' || /^(bob|bs)\.?$/i.test(s) ? 'Bs' : s;
}

// El código del pedido que se le muestra al cliente: letras y dígitos, sin más.
function cbCodigo(c) {
  const limpio = String(c === undefined || c === null ? '' : c).replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  // Un código que formara una palabra de la red de prohibidas no se muestra.
  return CB_PROHIBIDAS.test(cbCanon(limpio)) ? '' : limpio;
}

// La URL del QR: solo `https://`, con un dominio con nombre (la última parte empieza con una letra: nada de IP, de
// «localhost» ni de números sueltos), SIN usuario (`@`) ni puerto, sin espacios ni comillas. Hasta 2.000 caracteres.
// (La expresión es lineal: cada parte del dominio está acotada a 63 caracteres y separada por un punto.)
function cbUrlSegura(u) {
  const s = typeof u === 'string' ? u.trim() : '';
  return s.length > 0 && s.length <= 2000
    && /^https:\/\/(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?(?:[/?#][^\s<>"'@]*)?$/i.test(s);
}

// `cuerpoPanel` es el cuerpo completo de `configuracionFlujo`. Sale `activo:false`
// con todo lo demás vacío en cualquier duda: sin QR utilizable no hay cobro real.
function cbCobroReal(cuerpoPanel) {
  const r = cbEsObjeto(cuerpoPanel) ? cuerpoPanel : {};
  const cr = cbEsObjeto(r.cobroReal) ? r.cobroReal : null;
  const cb = cbEsObjeto(r.cobro) ? r.cobro : {};
  const qr = cbEsObjeto(cb.qr) ? cb.qr : {};
  const url = typeof qr.url === 'string' ? qr.url.trim() : '';
  const activo = cr !== null && cb.activo !== false && cbUrlSegura(url);
  if (!activo) {
    return {
      activo: false, qrUrl: '', titular: '', banco: '', pendiente: false, monto: null,
      pedidoRef: '', vencidoHaceMin: null, venceEl: '', regla: 1, enRevision: false,
    };
  }
  const monto = cbTotalValido(cb.monto);
  const vencido = typeof cb.vencidoHaceMin === 'number' && Number.isFinite(cb.vencidoHaceMin) && cb.vencidoHaceMin >= 0
    ? Math.floor(cb.vencidoHaceMin) : null;
  return {
    activo: true,
    qrUrl: url,
    titular: cbLinea(cr.nombreCuenta, 120),
    banco: cbLinea(cr.banco, 80),
    // Un QR esperando comprobante: lo dice el servidor mirando a ESTE teléfono.
    pendiente: cb.pendiente === true,
    monto: monto,
    pedidoRef: typeof cb.pedido === 'string' ? cbLinea(cb.pedido, 120) : '',
    vencidoHaceMin: vencido,
    // El último día de vigencia del QR (`aaaa-mm-dd`, el que registró el comercio). Solo se copia; `cbQrVencido` lo interpreta.
    // Tal cual, sin recortar a 10 ni limpiar: el servidor exige el formato exacto, y un valor ilegible aquí debe seguir siendo ilegible.
    venceEl: typeof cr.venceEl === 'string' ? cr.venceEl.slice(0, 40) : '',
    // Regla 2 del cobro (15 minutos, 3 intentos): solo el número 2 la enciende. `enRevision` = el cobro ya está con una persona (tercer intento inválido):
    // una foto más se manda igual al servidor, que la anota sin avisar de nuevo. Con la regla 1 nada de esto cambia.
    regla: cb.regla === 2 ? 2 : 1,
    enRevision: cb.regla === 2 && cb.enRevision === true,
  };
}

// El texto de una respuesta de Gemini (generateContent, o el nodo de LangChain con
// `simplify`). '' si vino un error o algo que no se reconoce.
function cbTextoDeGemini(j) {
  if (!j || typeof j !== 'object' || j.error) return '';
  const partes = (c) => (c && Array.isArray(c.parts))
    ? c.parts.map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n') : '';
  if (typeof j.content === 'string') return j.content;
  const c1 = partes(j.content);
  if (c1) return c1;
  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const c2 = cand ? partes(cand.content) : '';
  if (c2) return c2;
  for (const k of ['text', 'output', 'response']) {
    if (typeof j[k] === 'string' && j[k].trim()) return j[k];
  }
  return '';
}

// El ÚNICO objeto `{…}` de nivel superior del texto, ya interpretado. Si hay dos o
// más (una frase del modelo con otro JSON, un texto de la imagen que se coló) o no
// se puede interpretar, null: es ilegible y se pide de nuevo. Mejor pedirlo otra
// vez que elegir cuál de dos objetos creerle.
function cbObjetoUnico(texto) {
  const t = String(texto === undefined || texto === null ? '' : texto).slice(0, 20000);
  const objetos = [];
  let prof = 0;
  let ini = -1;
  let enCadena = false;
  let escape = false;
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (enCadena) {
      if (escape) escape = false;
      else if (ch === '\\') escape = true;
      else if (ch === '"') enCadena = false;
      continue;
    }
    if (ch === '"' && prof > 0) { enCadena = true; continue; }
    if (ch === '{') {
      if (prof === 0) ini = i;
      prof++;
    } else if (ch === '}' && prof > 0) {
      prof--;
      if (prof === 0) objetos.push(t.slice(ini, i + 1));
    }
  }
  if (objetos.length !== 1) return null;
  try {
    const o = JSON.parse(objetos[0]);
    return cbEsObjeto(o) ? o : null;
  } catch (e) {
    return null;
  }
}

// Un campo leído: un número finito tal cual, o un texto corto sin controles. Solo
// claves PROPIAS del objeto, y cualquier otra cosa (objeto, lista, booleano) es ''.
function cbCampoLeido(o, k, max) {
  if (!Object.prototype.hasOwnProperty.call(o, k)) return '';
  const v = o[k];
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v !== 'string') return '';
  return v.replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
}

// `respGemini` = el item que devolvió el nodo de Gemini (o el cuerpo de
// `generateContent`). Salen SEIS campos y `legible`; nada más. NO compara nada:
// compara el servidor, contra el total que se cotizó con el QR.
function cbLectura(respGemini) {
  const objeto = cbObjetoUnico(cbTextoDeGemini(respGemini)) || {};
  const leido = {
    monto: cbCampoLeido(objeto, 'monto', 40),
    cuentaDestino: cbCampoLeido(objeto, 'cuentaDestino', 60),
    nombreCuenta: cbCampoLeido(objeto, 'nombreCuenta', 120),
    fecha: cbCampoLeido(objeto, 'fecha', 40),
    hora: cbCampoLeido(objeto, 'hora', 20),
    banco: cbCampoLeido(objeto, 'banco', 80),
  };
  const legible = String(leido.monto) !== '' || String(leido.cuentaDestino) !== '';
  return { legible: legible, leido: leido };
}

// La respuesta completa de un HTTP (`{statusCode, body}`) con el cuerpo ya como objeto ({} si no se pudo leer).
function cbCuerpoDe(resp) {
  const r = cbEsObjeto(resp) ? resp : {};
  let cuerpo = r.body;
  if (typeof cuerpo === 'string') {
    try { cuerpo = JSON.parse(cuerpo); } catch (e) { cuerpo = {}; }
  }
  return { codigo: Number(r.statusCode), cuerpo: cbEsObjeto(cuerpo) ? cuerpo : {} };
}

// La ruta que devolvió `guardarComprobante` (200 `{ruta}`), o null: cualquier otra cosa (409, 413, 415, 502, un error de red, una ruta que no tiene la forma
// `tenants/<comercio>/comprobantes/<aaaa-mm-dd>/<nombre>.<jpg|png|webp|pdf>`) es «no se guardó». El cotejo corre igual, con `ruta: null`.
function cbRutaGuardada(resp) {
  const c = cbCuerpoDe(resp);
  if (c.codigo !== 200 || typeof c.cuerpo.ruta !== 'string') return null;
  const ruta = c.cuerpo.ruta;
  return ruta.length <= 300 && /^tenants\/[A-Za-z0-9_-]{1,60}\/comprobantes\/\d{4}-\d{2}-\d{2}\/[A-Za-z0-9_-]{1,100}\.(?:jpg|png|webp|pdf)$/.test(ruta) ? ruta : null;
}

// Listas CERRADAS. Todo lo que no está aquí es «sin_cotejo» (aviso al local + botón): nunca se adivina.
const CB_ESTADOS_VENTA = ['valido', 'aproximado', 'reintentar', 'en_revision', 'tardio', 'ya_resuelto'];

// Motivos de un comprobante que no se pudo leer: se pide uno más nítido (no hay una «diferencia» que decir).
const CB_MOTIVOS_NO_LEGIBLE = ['ilegible', 'falta_monto', 'falta_fecha', 'falta_destino'];

// Motivo del servidor -> frase en la forma que reconoce `cbDiferencia` (ahí se vuelve el texto fijo para el cliente).
const CB_FRASE_DEL_MOTIVO = {
  fecha_anterior: 'El comprobante es anterior al pedido',
  fecha_posterior: 'El comprobante tiene una fecha posterior',
  cuenta_distinta: 'El depósito fue a la cuenta',
  destino_no_coincide: 'El depósito fue a la cuenta',
  nombre_distinto: 'El depósito figura a',
  destino_no_verificable: 'El comprobante no muestra a qué cuenta',
};

// `respCotejo` = la respuesta completa de `Cotejar en el servidor` (`/cotejarComprobanteVenta`). Devuelve
//   {resultado, diferencias, importe, cierreId, causa}
// con `resultado` en el vocabulario que ya entiende el resto del flujo:
//   valido                     -> cuadra       (los datos coinciden; el local confirma en su banco)
//   aproximado                 -> aproximado   (al cliente, el mismo texto; al local, «datos casi coinciden, revisar»)
//   reintentar, no se lee      -> ilegible     (se pide uno más nítido)
//   reintentar, otro motivo    -> reintentar   (se dice la diferencia y se pide el correcto)
//   tardio | en_revision       -> sin_cotejo   con `causa` (aviso al local + botón)
//   ya_resuelto, repetido, o un estado que ya avisó -> ya_cotejado (sin segundo aviso)
//   TODO LO DEMÁS (cualquier 409, 4xx, 5xx, timeout, cuerpo ilegible, estado desconocido) -> sin_cotejo.
function cbResultadoVenta(respCotejo) {
  const c = cbCuerpoDe(respCotejo);
  const cuerpo = c.cuerpo;
  const salida = { resultado: 'sin_cotejo', diferencias: [], importe: null, cierreId: '', causa: '' };
  if (c.codigo !== 200) return salida;
  const estado = typeof cuerpo.estado === 'string' ? cuerpo.estado : '';
  if (CB_ESTADOS_VENTA.indexOf(estado) < 0) return salida;
  salida.importe = typeof cuerpo.importe === 'number' && Number.isFinite(cuerpo.importe) && cuerpo.importe > 0 ? cuerpo.importe : null;
  salida.cierreId = typeof cuerpo.cierreId === 'string' ? cbLinea(cuerpo.cierreId, 160) : '';
  const motivo = typeof cuerpo.motivo === 'string' ? cuerpo.motivo : '';
  if (estado === 'ya_resuelto') { salida.resultado = 'ya_cotejado'; return salida; }
  if (estado === 'reintentar') {
    if (CB_MOTIVOS_NO_LEGIBLE.indexOf(motivo) >= 0) { salida.resultado = 'ilegible'; return salida; }
    salida.resultado = 'reintentar';
    const leido = typeof cuerpo.montoLeido === 'number' && Number.isFinite(cuerpo.montoLeido) && cuerpo.montoLeido > 0 ? cuerpo.montoLeido : null;
    if (motivo === 'monto_menor' || motivo === 'monto_mayor' || motivo === 'monto_distinto') {
      if (leido !== null && salida.importe !== null) salida.diferencias = ['El comprobante dice ' + leido + ' y el pedido es de ' + salida.importe];
    } else if (Object.prototype.hasOwnProperty.call(CB_FRASE_DEL_MOTIVO, motivo)) {
      salida.diferencias = [CB_FRASE_DEL_MOTIVO[motivo]];
    }
    return salida;
  }
  // valido, aproximado, tardio, en_revision: el aviso al local sale UNA vez (lo dice el servidor); el mismo comprobante otra vez, o un estado que
  // el servidor ya avisó, no manda un segundo aviso.
  if (cuerpo.repetido === true || cuerpo.avisarComercio !== true) { salida.resultado = 'ya_cotejado'; return salida; }
  if (estado === 'valido') { salida.resultado = 'cuadra'; return salida; }
  if (estado === 'aproximado') { salida.resultado = 'aproximado'; return salida; }
  salida.resultado = 'sin_cotejo';
  salida.causa = estado;
  return salida;
}

// El estado que va en {{1}} del aviso. null = este resultado no genera aviso
// (`ya_cotejado`). Sin resultado de cotejo (`sin_qr` o vacío) es el plan B.
function cbEstadoParaAviso(resultado) {
  if (resultado === 'cuadra') return 'comprobante: datos coinciden';
  if (resultado === 'aproximado') return 'comprobante: datos casi coinciden, revisar';
  if (resultado === 'no_cuadra') return 'comprobante: NO coinciden';
  if (resultado === 'ilegible') return 'comprobante ilegible';
  if (resultado === 'sin_cotejo') return 'comprobante sin cotejar';
  if (resultado === 'ya_cotejado') return null;
  if (resultado === 'simulado') return 'PRUEBA: cobro SIMULADO, sin dinero';
  if (resultado === 'qr_vencido') return 'QR vencido: coordinar el pago';
  return 'sin QR: cobrar al entregar';
}

// Un importe como lo escribe el servidor («21.00», «1,5», «1.234,50») en la forma de Bolivia, sin decimales sobrantes: «21», «1,50», «1234,50». Con un solo
// separador, es el decimal; con los dos, el que aparece último es el decimal. Un valor que no es un número finito se deja como llegó (ya solo trae dígitos y separadores).
function cbImporteDelServidor(t) {
  const x = String(t);
  const ult = Math.max(x.lastIndexOf('.'), x.lastIndexOf(','));
  const n = ult < 0 ? Number(x) : Number(x.slice(0, ult).replace(/[.,]/g, '') + '.' + x.slice(ult + 1));
  return Number.isFinite(n) ? cbMonto(n) : x;
}

// Las diferencias que da el servidor, a una frase FIJA. Lo leído de la imagen (un
// nombre, una cuenta) NUNCA se copia al cliente: ahí puede venir cualquier texto.
// Solo pasan dos números, que el servidor ya tradujo de la lectura. Reconoce la
// primera que sabe decir; si no reconoce ninguna, ''.
function cbDiferencia(diferencias, moneda) {
  const lista = Array.isArray(diferencias) ? diferencias : [diferencias];
  for (let i = 0; i < lista.length; i++) {
    const d = String(lista[i] === undefined || lista[i] === null ? '' : lista[i]);
    // Cada patrón se ancla al INICIO de la frase del servidor: un nombre leído de la
    // imagen que repita otra frase no cambia cuál se reconoce.
    const m = /^\s*El comprobante dice (\d+(?:[.,]\d+)*) y el pedido es de (\d+(?:[.,]\d+)*)/i.exec(d);
    if (m) return 'el comprobante dice ' + cbImporteDelServidor(m[1]) + ' ' + cbMoneda(moneda) + ' y tu pedido es de ' + cbImporteDelServidor(m[2]) + ' ' + cbMoneda(moneda);
    if (/^\s*No se pudo leer el importe/i.test(d)) return 'no pude leer el importe';
    if (/^\s*No se pudo leer la fecha/i.test(d)) return 'no pude leer la fecha';
    if (/^\s*El comprobante es anterior al pedido/i.test(d)) return 'la fecha del comprobante es anterior a tu pedido';
    if (/^\s*El comprobante tiene una fecha posterior/i.test(d)) return 'la fecha del comprobante no es correcta';
    if (/^\s*El comprobante no muestra a qué cuenta/i.test(d)) return 'en el comprobante no se ve a qué cuenta se depositó';
    if (/^\s*El depósito fue a la cuenta/i.test(d)) return 'la cuenta de destino no es la del QR';
    if (/^\s*El depósito figura a/i.test(d)) return 'el nombre del destinatario no coincide con el de la cuenta';
  }
  return '';
}

// =============================================================================
// AVISOS DEL FLUJO DE ANTONIO (prefijo `av` / `AV_`): HUECO DECLARADO en PROPIO.md
// =============================================================================
// COPIA, declaración por declaración y BYTE A BYTE, de `Flujos/experimental/venta-minima/src/lib/avisos.js` (rama #519): el módulo común de avisos todavía no existe. Solo lo
// que usan el aviso mínimo de PR-2 (texto libre a Antonio, dentro de las 24 h) y los ganchos de PR-3 (`avPlantilla`). Cada declaración tiene su prueba contra el origen en
// `huecos.test.ts`. Sin `require`, `URL`, `Buffer` ni `crypto`.

// La copia local de la red de palabras que el asistente jamás dice (la de `comun.js` manda si existe).
const AV_PROHIBIDAS = /validad|confirmad|pagad[oa]|acreditad|verificad|recibimos\s+tu\s+pago|ya lo prepar|lo (est[aá](n|mos)|estoy) prepar|lo preparamos|te avisa(mos|remos)|en camino|te llama(mos|remos)|te escribir[aá]n|lo consulto|acredit|recib\S{0,40}\s+(tu|el|su|mi|un|este|ese|la|tus|sus|los)\s+(pago|transferencia|dep[oó]sito|abono)s?|lleg[oó]\s+(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)|(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad)|confirm(amos|ó|o)\s+(tu|tus|su|sus|la|el|lo|los|las)\b|\b(?:est[aá]n?|qued[oó]|queda|quedan|quedaron|fue|fueron|ya)\s+(?:ya\s+)?reservad|reserva\s+((est[aá]|qued[oó])\s+)?(registrad|agendad)|reservamos tu|\b(?:te|le|les|se|lo|la|ya)\s+confirm(?:o|amos|é|ó|aron)\b|gracias\s+por\s+(tu|su|el)\s+(pago|transferencia|dep[oó]sito|abono)s?|\b(lleg|ingres|entr)(o|ó|aron)\s+(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)|\b(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|\brecib(imos|i|í|ido)\s+(el|la|tu|su)\s+(dinero|plata|monto)|(pago|transferencia|dep[oó]sito|abono|cobro)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+|qued[oó]\s+|se\s+)?(ya\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad|aceptad|completad|procesad|reflejad|comprobad)|\breflej(o|ó)\s+(tu|el|su)\s+(pago|transferencia|dep[oó]sito|abono)|\b(verificamos|comprobamos|validamos|aceptamos|tenemos|vimos|cobramos)\s+(tu|tus|su|sus|el|la)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata)|\bpago\s+(listo|ok)\b|\b(tu|su|el)\s+pago\s+(ya\s+)?(est[aá]|qued[oó])\s+(ya\s+)?(listo|ok|en\s+orden|bien|correcto|completo|hecho)\b|en\s+orden\s+con\s+(tu|su|el)\s+pago|\bsaldad[oa]s?\b|\b(pedido|cuenta|pago|total|orden|deuda)s?\s+((ya\s+)?(est[aá]n?|qued[oó]|fue|queda)\s+)?(ya\s+)?cancelad[oa]s?\b|\bya\s+nos\s+pag(aste|o|ó|aron)\b|\bgracias\s+por\s+pagar\b|\bya\s+pagaste\W{0,3}\s*(muchas\s+)?gracias|\brecib(imos|i|í|ido)\s+(bs\.?\s*|bob\s*)?\d+([.,]\d+)?\s*(bs|bob|bolivianos)\b|\bconfirm(amos|e|é)\s+que\s+(ya\s+)?pag|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?se\s+reflej/i;

const AV_ENLACE = /(?:https?:\/\/|www\.)\S+|\b(?:wa\.me|t\.me|bit\.ly|goo\.gl|tinyurl\.com)\/\S*|\b[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:com|net|org|bo|me|io|co|app|ly|link|info|biz|xyz|site|online)\b(?:\/\S*)?/gi;

function avProhibidas() {
  try {
    if (typeof VM_PROHIBIDAS !== 'undefined' && VM_PROHIBIDAS instanceof RegExp) return VM_PROHIBIDAS;
  } catch (e) { /* VM_PROHIBIDAS aún sin declarar: rige la copia local */ }
  return AV_PROHIBIDAS;
}

// Confusables latino/cirílico/griego que se pliegan a ASCII SOLO para comparar (S-1). Las dos cadenas van en paralelo, letra
// por letra. El texto que sale nunca se pliega, y las letras latinas no están en la tabla (un texto legítimo no cambia).
const AV_CONFUSABLES_DE = 'аеорсухіјѕԁһӏ' + 'αεικορτυχνηβı';

const AV_CONFUSABLES_A = 'aeopcyxijsdhl' + 'aeikoptuxvnbi';

const AV_OMITIDO = '[texto omitido]';

/** La forma en que se COMPARA (S-1): NFKC, sin controles C1 ni caracteres de formato, NFD sin marcas, en minúsculas y con los confusables plegados. */
function avCanon(t) {
  return String(t === undefined || t === null ? '' : t).normalize('NFKC').replace(/[\u0080-\u009f]/g, '').replace(/\p{Cf}/gu, '').replace(/[\u115f\u1160\u3164\uffa0\u2800]/g, '')
    .normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[Ͱ-ϿЀ-ԯı]/g, (c) => {
      const i = AV_CONFUSABLES_DE.indexOf(c);
      return i < 0 ? c : AV_CONFUSABLES_A.charAt(i);
    });
}

/** La forma canónica sin puntuación: todo lo que no es letra ni número es un espacio. */
function avNorm(t) {
  return avCanon(t).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

// Las palabras de `s` que caen dentro de una coincidencia de la red, mirando la forma canónica (con puntuación) y la sin
// puntuación, cada una con las palabras unidas por un espacio. `separadores[k]` es el espacio que antecede a la palabra `k`.
function avPalabrasProhibidas(s) {
  const re0 = avProhibidas();
  const base = re0.flags.replace(/[gy]/g, '');
  const partes = s.split(/(\s+)/);
  const palabras = [];
  const separadores = [];
  let sep = '';
  for (let i = 0; i < partes.length; i++) {
    if (i % 2 === 1) { sep = partes[i]; continue; }
    if (partes[i] === '') continue;
    palabras.push(partes[i]);
    separadores.push(sep);
    sep = '';
  }
  const marcadas = palabras.map(() => false);
  const vacias = palabras.map(() => false);
  for (const forma of [avCanon, avNorm]) {
    const spans = [];
    let unido = '';
    palabras.forEach((w, k) => {
      const f = forma(w);
      if (f === '') { spans.push(null); if (forma === avNorm) vacias[k] = true; return; }
      if (unido !== '') unido += ' ';
      spans.push([unido.length, unido.length + f.length]);
      unido += f;
    });
    const re = new RegExp(re0.source, base + 'g');
    let m = re.exec(unido);
    while (m) {
      const a = m.index;
      const b = a + m[0].length;
      spans.forEach((p, k) => { if (p && p[0] < b && p[1] > a) marcadas[k] = true; });
      if (m[0].length === 0) re.lastIndex++;
      m = re.exec(unido);
    }
  }
  // Una palabra sin letras ni números («·», «-») entre dos marcadas se va con ellas: queda UNA marca.
  for (let k = 0; k < palabras.length; k++) {
    if (!marcadas[k]) continue;
    let j = k + 1;
    while (j < palabras.length && vacias[j] && !marcadas[j]) j++;
    if (j < palabras.length && marcadas[j]) for (let x = k + 1; x < j; x++) marcadas[x] = true;
  }
  return { palabras, separadores, marcadas, cola: sep };
}

// Cada PALABRA que forma parte de una coincidencia de la red (en la forma canónica o en la sin puntuación) se cambia por
// «[texto omitido]» (una marca por racha). No se corta ninguna palabra ni se normaliza nada fuera de la coincidencia. Llega a
// un punto fijo: tras reemplazar se vuelve a probar (hasta 3 pasadas) y, si aún coincide, devuelve solo la marca.
function avSinProhibidas(t) {
  let s = String(t === undefined || t === null ? '' : t);
  for (let pasada = 0; pasada < 3; pasada++) {
    const r = avPalabrasProhibidas(s);
    if (!r.marcadas.some(Boolean)) return s;
    let salida = '';
    let enMarca = false;
    r.palabras.forEach((w, k) => {
      if (r.marcadas[k]) {
        if (!enMarca) salida += r.separadores[k] + AV_OMITIDO;
        enMarca = true;
      } else {
        salida += r.separadores[k] + w;
        enMarca = false;
      }
    });
    s = salida + r.cola;
  }
  const re = avProhibidas();
  const rx = new RegExp(re.source, re.flags.replace(/[gy]/g, ''));
  return rx.test(avCanon(s)) || rx.test(avNorm(s)) ? AV_OMITIDO : s;
}

function avDigitos(v) {
  return String(v === undefined || v === null ? '' : v).replace(/\D/g, '');
}

/** Quita, sin regex (tiempo lineal), los espacios y los «·» del principio y del final. */
function avSinBordes(s) {
  const sep = (c) => c === '·' || /\s/.test(c);
  let i = 0;
  let j = s.length;
  while (i < j && sep(s.charAt(i))) i++;
  while (j > i && sep(s.charAt(j - 1))) j--;
  return s.slice(i, j);
}

/** Recorta a `n` puntos de código sin partir un par sustituto (acotado: solo mira los primeros `2n` caracteres). */
function avCortar(s, n) {
  return s.length > n ? Array.from(s.slice(0, n * 2)).slice(0, n).join('') : s;
}

/**
 * Una sola línea limpia: sin saltos ni tabuladores (quedan « · »), sin enlaces («[enlace omitido]»; una abreviatura con punto
 * pegada a la palabra siguiente, como «Nro.123» o «Av.Arce», recibe un espacio: «Nro. 123», «Av. Arce»), sin `{}<>&` ni marcas
 * de formato de WhatsApp (`* _ ~` y la comilla invertida), sin palabras prohibidas (cada palabra afectada, entera, por
 * «[texto omitido]»), sin espacios repetidos y con tope de caracteres. Con `opc.cocina` se quitan además los números largos
 * (teléfonos, cuentas, documentos). Devuelve '' si no queda nada.
 * TIEMPO LINEAL: el texto se recorta a `max * 2` antes de aplicar ninguna expresión regular y otra vez después de NFKC (una
 * ligadura como «㏂» crece 4×), y los bordes « · » se quitan a mano (la forma `(\s*·\s*)+$` tenía retroceso exponencial: 24
 * «· » seguidos tardaban 1,6 s y 90 no terminaban).
 */
function avLimpio(t, max, opc) {
  const tope = (Number.isFinite(max) && max > 0) ? Math.floor(max) : 500;
  let s = avCortar((t === undefined || t === null) ? '' : String(t), tope * 2);
  // NFKC (ancho completo, ligaduras) y sin caracteres de formato, salvo «º» y «ª» (NFKC los cambia por «o» y «a»: «N.º»).
  // Tampoco «…»: NFKC lo cambiaría por «...» y la marca «… y N más» de una lista recortada dejaría de ser la que armó el código.
  s = s.split(/([ºª…])/).map((p, i) => (i % 2 ? p : p.normalize('NFKC'))).join('').replace(/\p{Cf}/gu, '');
  s = avCortar(s, tope * 2);
  // El punto ideográfico («。» U+3002) y el de media anchura («｡» U+FF61) NFKC no los lleva a «.»: se normalizan aquí, antes del filtro.
  s = s.replace(/[。｡]/g, '.');
  s = s.replace(AV_ENLACE, ' [enlace omitido] ');
  s = s.replace(/[\r\n\t\u000b\u000c\u0085\u2028\u2029]+/g, ' · ');
  s = s.replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060\ufeff]/g, '');
  s = s.replace(/[{}<>&*_~`]/g, ' ');
  // Un punto pegado a lo que sigue (letra.letra, letra.número o número.letras) recibe un espacio: así «Nro.123», «Av.Arce» o
  // «dpto.4B» llegan enteros, y «malo.test/x» o «x.ru» no quedan como un enlace que WhatsApp convierta en tocable. Los
  // decimales y las horas («4.50», «12.30», «1.25L») no se tocan.
  s = s.replace(/(?<=[\p{L}\p{M}])(?<![ºª])\.(?=[\p{L}\p{M}\p{N}])(?![ºª])|(?<=\p{N})\.(?=\p{L}{2})/gu, '. ');
  if (opc && opc.cocina) {
    s = s.replace(/\+?\d[\d\s.-]{5,}\d/g, (m) => (m.replace(/\D/g, '').length >= 7 ? '…' : m));
    s = s.replace(/\d{7,}/g, '…');
  }
  // Se colapsan espacios y « · » ANTES de comparar con la red: quitar `*_~` deja huecos que juntan frases («te *avisamos»).
  s = avSinBordes(s.replace(/\s{2,}/g, ' '));
  s = avSinBordes(s.replace(/(?:\s·){2,}/g, ' ·'));
  s = avSinBordes(avSinProhibidas(s).replace(/\s{2,}/g, ' '));
  if (Array.from(s).length > tope) {
    // El corte PUEDE volver a formar una coincidencia de la red («confirmo tubos» recortado a «confirmo tu»): tras cortar se vuelve
    // a sanear, y como la marca es más larga que una palabra corta, se vuelve a cortar (hasta 4 vueltas, siempre acotado).
    for (let vuelta = 0; vuelta < 4; vuelta++) {
      s = Array.from(s).slice(0, tope).join('');
      // Un corte que cae dentro de una marca («[texto omit») se retrocede hasta el corchete que la abre.
      const ab = s.lastIndexOf('[');
      if (ab >= 0 && ab > s.lastIndexOf(']')) s = s.slice(0, ab);
      s = avSinBordes(avSinProhibidas(avSinBordes(s)).replace(/\s{2,}/g, ' '));
      if (Array.from(s).length <= tope) break;
    }
  }
  return avAjustarFinal(s, tope);
}

/** Verdadero si `s` coincide con la red en la forma canónica o en la sin puntuación (la misma comprobación de `avSinProhibidas`). */
function avCoincide(s) {
  const re = avProhibidas();
  const rx = new RegExp(re.source, re.flags.replace(/[gy]/g, ''));
  return rx.test(avCanon(s)) || rx.test(avNorm(s));
}

/**
 * Última garantía de `avLimpio`: el resultado respeta el tope y NO coincide con la red. Si algo falla, se quitan palabras
 * ENTERAS del final hasta que cumpla (y, en el peor caso, devuelve '').
 */
function avAjustarFinal(s, tope) {
  if (Array.from(s).length <= tope && !avCoincide(s)) return s;
  const palabras = s.split(' ');
  while (palabras.length > 0) {
    palabras.pop();
    const t = avSinBordes(palabras.join(' '));
    if (Array.from(t).length <= tope && !avCoincide(t)) return t;
  }
  return '';
}

