// «¿Tienes imágenes?», «¿me mandas una foto del libro?», «¿tienes capturas?»: el flujo NO envía imágenes del libro (solo existe el QR como imagen saliente).
function raPideImagenes(n) {
  const palabras = n === '' ? 0 : n.split(' ').length;
